Author: jlaznarte<br>Date: Wed Jun  4 04:36:27 2008<br>New Revision: 151<p>Added:<br>   trunk/tsDyn/R/ncgstar.R<br>   trunk/tsDyn/test/<br>   trunk/tsDyn/test/montecarlo.R   (contents, props changed)<br>Modified:<br>   trunk/tsDyn/NAMESPACE<br>   trunk/tsDyn/R/ncstar.R<p>Log:<br>Include the Gaussian transition function-based NCSTAR.<br>Also include a script to perform montecarlo experiments<br>with the models.<p><p>Modified: trunk/tsDyn/NAMESPACE<br>==============================================================================<br>--- trunk/tsDyn/NAMESPACE	(original)<br>+++ trunk/tsDyn/NAMESPACE	Wed Jun  4 04:36:27 2008<br>@@ -4,21 +4,16 @@<br> importFrom(tseriesChaos, d2)<br> importFrom(nnet, nnet)<br> importFrom(tseries, na.remove)<br>-importFrom(Matrix, norm)<br> export(nlar, mse, MAPE, selectSETAR, selectLSTAR, selectNNET,<br>        autopairs, autotriples, autotriples.rgl,<br>        delta, delta.test, delta.lin, delta.lin.test,<br>-       llar, llar.predict, llar.fitted, sigmoid, dsigmoid,	<br>-       setar, lstar, star, ncstar, ncstar.predefined, startingValues.ncstar, <br>-       availableModels, nlarDialog, <br>-       linear, isLinear, nnetTs, aar, star,<br>-       TVAR, TVECM,TVAR_LRtest, TAR_simul, TVAR_simul, TVECM_SeoTest, linear2)<br>+       llar, llar.predict, llar.fitted, sigmoid, dsigmoid,<br>+       setar, lstar, star, availableModels,<br>+       nlarDialog, linear, isLinear, nnetTs, aar,<br>+       star, ncstar, ncstar.predefined, ncgstar, ncgstar.predefined)<br> S3method(extend, list)<br> S3method(isLinear, lstar)<br> S3method(toLatex, setar)<br>-S3method(toLatex, TVAR)<br>-S3method(toLatex, TVECM)<br>-S3method(toLatex, VAR)<br> S3method(plot, nlar)<br> S3method(plot, setar)<br> S3method(plot, lstar)<br>@@ -32,44 +27,24 @@<br> S3method(print, lstar)<br> S3method(print, star)<br> S3method(print, aar)<br>-S3method(print, TVAR)<br>-S3method(print, TVECM)<br>-S3method(print, VAR)<br> S3method(summary, nlar)<br> S3method(summary, linear)<br> S3method(summary, setar)<br> S3method(summary, lstar)<br> S3method(summary, aar)<br>-S3method(summary, TVAR)<br>-S3method(summary, TVECM)<br>-S3method(summary, VAR)<br> S3method(print, summary.nlar)<br> S3method(print, summary.linear)<br> S3method(print, summary.setar)<br> S3method(print, summary.lstar)<br> S3method(print, summary.aar)<br>-S3method(print, summary.TVAR)<br>-S3method(print, summary.TVECM)<br>-S3method(print, summary.VAR)<br> S3method(residuals, nlar)<br>-S3method(deviance, nlar)<br> S3method(fitted, nlar)<br> S3method(coef, nlar)<br> S3method(AIC, nlar)<br>-S3method(BIC, nlar)<br> S3method(MAPE, nlar)<br> S3method(mse, nlar)<br>-S3method(coef, nlVar)<br>-S3method(AIC, nlVar)<br>-S3method(BIC, nlVar)<br>-S3method(BIC, lm)<br>-S3method(logLik, nlVar)<br>-S3method(residuals, nlVar)<br>-S3method(deviance, nlVar)<br>-S3method(fitted, nlVar)<br> S3method(print, llar)<br> S3method(plot, llar)<br> S3method(as.data.frame, llar)<br>-<br> <br> useDynLib(tsDyn)<p>Added: trunk/tsDyn/R/ncgstar.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/ncgstar.R	Wed Jun  4 04:36:27 2008<br>@@ -0,0 +1,981 @@<br>+## Copyright (C) 2005, 2006, 2007, 2008  Antonio, Fabio Di Narzo;<br>+##                                                           Jos� Luis Aznarte M.<br>+##<br>+## This program is free software; you can redistribute it and/or modify<br>+## it under the terms of the GNU General Public License as published by<br>+## the Free Software Foundation; either version 2, or (at your option)<br>+## any later version.<br>+##<br>+## This program is distributed in the hope that it will be useful, but<br>+## WITHOUT ANY WARRANTY; without even the implied warranty of<br>+## MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU<br>+## General Public License for more details.<br>+##<br>+## A copy of the GNU General Public License is available via WWW at<br>+## <a href="http://www.gnu.org/copyleft/gpl.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://www.gnu.org/copyleft/gpl.html&amp;source=gmail&amp;ust=1792465495967000&amp;usg=AOvVaw2WZelVmeHI6VtdHOH6gk9r">http://www.gnu.org/copyleft/gpl.html</a>.  You can also obtain it by<br>+## writing to the Free Software Foundation, Inc., 59 Temple Place,<br>+## Suite 330, Boston, MA  02111-1307  USA.<br>+<br>+# phi2 = c(gamma, th[1,], th[2,], ..., th[m,])<br>+<br>+# Gaussian transition function<br>+# z: threshold variable(s)<br>+# gamma: smoothing parameter(s)<br>+# th: threshold parameters, one vector for each regime<br>+GG &lt;- function(z, gamma, th) {<br>+  regimes &lt;- length(gamma)<br>+  n.used &lt;- NROW(z)<br>+  result &lt;- array(NA, c(n.used, regimes))<br>+<br>+  for(i in 1:regimes)<br>+      result[,i] &lt;- apply(exp( - gamma * (t(apply(z, 1, &quot;-&quot;, th[i,])))^2), 1, prod)<br>+  result<br>+}<br>+<br>+#Fitted values, given parameters<br>+# phi1: matrix of linear parameters<br>+# phi2omega: vector of tr. functions&#39; parameters<br>+#                                     (gamma_{1...p}, th{1...p}, omega_{1...p})<br>+FF &lt;- function(xx, phi1, phi2) {<br>+  noRegimes &lt;- NROW(phi1)<br>+  x_t &lt;- cbind(1,xx)<br>+<br>+  gamma &lt;- phi2[1:noRegimes - 1]<br>+  th &lt;- phi2[noRegimes:length(phi2)]<br>+  dim(th) &lt;- c(NCOL(xx), noRegimes - 1)<br>+<br>+  trfun &lt;- cbind(1, GG(xx, gamma, th))<br>+  local &lt;- (x_t %*% t(phi1)) * trfun;<br>+  result &lt;- apply(local, 1, sum)<br>+  result<br>+}<br>+<br>+computeGradient &lt;- function(object, ...)<br>+  UseMethod(&quot;computeGradient&quot;)<br>+<br>+# Computes the gradient<br>+#<br>+# object: a valid STAR model.<br>+#<br>+# Returns a list of the gradients with respect to  the linear and<br>+#     nonlinear parameters<br>+computeGradient.ncstar &lt;- function(object, ...)<br>+{<br>+ <br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+  n.used &lt;- NROW(object$str$xx);<br>+  x_t &lt;- cbind(1, object$str$xx);<br>+  xx &lt;- object$str$xx;<br>+  p &lt;- NCOL(x_t)<br>+  q &lt;- NCOL(xx)<br>+<br>+  phi2 &lt;- object$model.specific$phi2<br>+  gamma &lt;- phi2[1:noRegimes - 1]<br>+  th &lt;- phi2[noRegimes:length(phi2)]<br>+  dim(th) &lt;- c(q, noRegimes - 1)<br>+<br>+  # linear parameters<br>+  phi1 &lt;- object$model.specific$phi1;<br>+<br>+  fX &lt;- GG(xx, gamma, th);<br>+#  dfX &lt;- GGd(xx, gamma, th);<br>+<br>+  tsum &lt;- array(NA, c(n.used, noRegimes - 1, q))<br>+  tsum2 &lt;- array(NA, c(n.used, noRegimes - 1))<br>+  for (i in 1:(noRegimes-1)) <br>+    tsum[,i,] &lt;- t(apply(xx, 1, &quot;-&quot;, th[i,]))<br>+  for (i in 1:(noRegimes-1)) <br>+    tsum2[,i] &lt;- apply(tsum[,i,]^2, 1, sum)<br>+  <br>+  gPhi1 &lt;- array(x_t, c(n.used, noRegimes * p));<br>+  for (i in 2:noRegimes) <br>+    gPhi1[,(i * p - p + 1):(i * p)] &lt;- x_t * fX[,i-1] ;<br>+<br>+  ggamma &lt;- array(0, c(n.used, noRegimes-1));<br>+  for (i in 1:(noRegimes-1))<br>+    ggamma[,i] &lt;- - fX[,i] * tsum2[,i];<br>+<br>+  gth &lt;- array(0, c(n.used, (noRegimes-1), q));<br>+  for (i in 1:(noRegimes - 1))<br>+    for (j in 1:q)<br>+      gth[, i, j] &lt;- 2 * gamma * tsum[,i,j] * fX[,i]<br>+  dim(gth) &lt;- c(n.used, (noRegimes - 1) * q)<br>+  <br>+  return(cbind(gPhi1, ggamma, gth))<br>+<br>+}<br>+<br>+testRegime &lt;- function(object, ...)<br>+  UseMethod(&quot;testRegime&quot;)<br>+<br>+# Tests (within the LM framework), being the null hypothesis H_0 that the<br>+#    model &#39;object&#39; is complex enough and the alternative H_1 that an extra<br>+#    regime should be considered.<br>+#<br>+# object: a STAR model already built with at least 2 regimes.<br>+# G: the gradient matrix obtained by using computeGradient()<br>+# rob: boolean indicating if robust tests should be used or not.<br>+# sig: significance level of the tests<br>+# <br>+# returns a list containing the p-value of the F statistic and a boolean,<br>+#      true if there is some remaining nonlinearity and false otherwise.<br>+testRegime.ncstar &lt;- function(object, G, rob=FALSE, sig=0.05, trace = TRUE, ...)<br>+{<br>+<br>+  e &lt;-  object$residuals;<br>+  nG &lt;- NCOL(G);<br>+  T &lt;- length(e);<br>+  xx &lt;- object$str$xx<br>+<br>+  normG &lt;- norm(Matrix(t(G)) %*% e)<br>+  norm2G &lt;-  sum(abs(t(G) %*% e)^2)^(1/2) <br>+#  cat(&quot;norm2G = &quot;, norm2G, &quot;normG = &quot;, normG, &quot;
&quot;);<br>+<br>+  # Compute the rank of G&#39; * G<br>+  G2 &lt;- t(G) %*% G;<br>+  s &lt;- svd(G2);<br>+  tol &lt;- max(dim(G2)) * s[1]$d * 2.2204e-16<br>+#  rG &lt;- sum(svd(G2)$d &gt; tol); # Alternative methods<br>+  rG &lt;- qr(G2, tol)$rank<br>+#  cat(&quot;rango G = &quot;, rG, &quot;
&quot;);<br>+<br>+  if (normG &gt; 1e-6) {<br>+    if(rG &lt; nG) {<br>+#      cat(&quot;A1
&quot;)<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda &gt; 0.99999));<br>+      GPCA &lt;- t(PC %*% t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+#      b &lt;- lm.fit(x = GPCA, y = e)$coefficients<br>+      b &lt;- lm(e ~ . -1, data = data.frame(GPCA))$coefficients<br>+      u &lt;-  e - GPCA %*% b;<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+#      cat(&quot;A2
&quot;)<br>+#      b &lt;- lm.fit(x = G, y = e)$coefficients;<br>+      b &lt;- lm(e ~ . -1, data=data.frame(G))$coefficients;<br>+      u &lt;- e - G %*% b;<br>+      xH0 &lt;- G;<br>+    }<br>+  } else {<br>+    u &lt;- e;<br>+    if(rG &lt; nG) {<br>+#     cat(&quot;B1
&quot;)<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda&gt; 0.99999));<br>+      GPCA &lt;- t(PC%*%t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+      xH0 = G;<br>+    }<br>+  }<br>+<br>+  SSE0 &lt;- sum(u^2);<br>+<br>+  # Regressors under the alternative:<br>+  xH1 &lt;- cbind(xx^2, xx^3)#, xx^4)<br>+  <br>+  Z &lt;- cbind(xH0, xH1)<br>+<br>+  # Standarize the regressors<br>+  nZ &lt;- NCOL(Z);<br>+  sdZ &lt;- sd(Z)<br>+  dim(sdZ) &lt;- c(1, nZ)<br>+<br>+  sdZ &lt;- kronecker(matrix(1, T, 1), sdZ) # repeat sdZ T rows<br>+  Z[,2:nZ] &lt;- Z[,2:nZ] / sdZ[,2:nZ]<br>+<br>+  # Compute the rank of Z<br>+  s &lt;- svd(Z);<br>+  tol &lt;- max(dim(Z)) * s[1]$d * 2.2204e-16<br>+  rZ &lt;- qr(Z, tol)$rank<br>+  if(rZ &lt; NCOL(Z)) stop(&quot;Multicollinearity problem.
&quot;)<br>+<br>+ # Nonlinear model (Alternative hypothesis)<br>+  c &lt;- lm.fit(x = Z, y = u)$coefficients<br>+#  c &lt;- lm(u ~ . - 1, data=data.frame(Z))$coefficients<br>+  dim(c) &lt;- c(NCOL(Z), 1);<br>+  v &lt;- u - Z %*% c;<br>+  SSE &lt;- sum(v^2);<br>+<br>+  # Compute the third order statistic<br>+  nxH0 &lt;- NCOL(xH0);<br>+  nxH1 &lt;- NCOL(xH1);<br>+  <br>+  F = ((SSE0 - SSE) / nxH1) / (SSE / (T - nxH0 - nxH1));<br>+<br>+  pValue &lt;- pf(F, nxH1, T - nxH0 - nxH1, lower.tail = FALSE);<br>+<br>+  if (pValue &gt;= sig) {<br>+    return(list(remainingNonLinearity = FALSE, pValue = pValue));<br>+  }<br>+  else {<br>+    return(list(remainingNonLinearity = TRUE, pValue = pValue));<br>+  }<br>+}<br>+<br>+addRegime &lt;- function(object, ...)<br>+  UseMethod(&quot;addRegime&quot;)<br>+<br>+addRegime.ncstar &lt;- function(object)<br>+{<br>+<br>+  noRegimes &lt;- object$model.specific$noRegimes<br>+  xx &lt;- object$str$xx<br>+  phi2 &lt;- object$model.specific$phi2<br>+<br>+  if(noRegimes == 1) {<br>+<br>+    gamma &lt;- 0<br>+    th &lt;- rnorm(NCOL(xx))<br>+    <br>+    phi2 &lt;- c(gamma, th);<br>+<br>+    phi1 &lt;-   object$model.specific$phi1<br>+    phi1 &lt;-   rbind(object$model.specific$phi1, rnorm(NCOL(xx) + 1));<br>+    <br>+  }<br>+  else {<br>+    # phi2 contains parameters gamma and th for each regime<br>+    gamma &lt;- phi2[1:noRegimes - 1]<br>+    th &lt;- phi2[noRegimes:length(phi2)]<br>+    dim(th) &lt;- c(NCOL(xx), noRegimes - 1)<br>+      <br>+    gamma[noRegimes] &lt;- 0.0; # Add one gamma<br>+    th &lt;- cbind(th, rnorm(NCOL(xx)));        # Add one th<br>+<br>+    phi2 &lt;- c(gamma, th);<br>+<br>+    # phi1 (one vector for each regime)<br>+    phi1 &lt;-   object$model.specific$phi1<br>+    phi1 &lt;-   rbind(object$model.specific$phi1, rnorm(NCOL(xx) + 1));<br>+  }<br>+<br>+  # Update the object<br>+  object$model.specific$noRegimes &lt;- object$model.specific$noRegimes + 1;<br>+  object$noRegimes &lt;- object$noRegimes + 1;<br>+  <br>+  object$model.specific$phi1 &lt;- phi1<br>+  object$model.specific$phi2 &lt;- phi2<br>+  <br>+  object$model.specific$coefficients &lt;- c(phi1, phi2);<br>+  object$coefficients &lt;- c(phi1, phi2);<br>+  object$model.specific$k &lt;- length(object$coefficients)<br>+  object$k &lt;- length(object$coefficients);<br>+  <br>+  return(object);<br>+  <br>+}<br>+<br>+startingValues &lt;- function(object, ...)<br>+  UseMethod(&quot;startingValues&quot;)<br>+<br>+startingValues.ncstar &lt;- function(object, trace=TRUE, svIter, ...)<br>+{<br>+<br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+  xx &lt;- object$str$xx;<br>+  x_t &lt;- cbind(1, xx)<br>+  yy &lt;- object$str$yy;<br>+  n.used &lt;- NROW(object$str$xx);<br>+  p &lt;- NCOL(x_t)<br>+  q &lt;- NCOL(xx)<br>+  local1 &lt;- array(x_t,  c(n.used * NCOL(x_t), noRegimes))<br>+  local2 &lt;- array(0, c(NROW(xx), noRegimes))<br>+  <br>+  phi2 &lt;- object$model.specific$phi2<br>+  gamma &lt;- phi2[1:noRegimes - 1]<br>+  th &lt;- phi2[noRegimes:length(phi2)]<br>+  dim(th) &lt;- c(NCOL(xx), noRegimes - 1)<br>+  <br>+  # Fix &#39;svIter&#39; random starting values for th<br>+  newTh &lt;- c(rnorm(svIter * q, mean=mean(xx[,1]), sd=sd(xx[,1])))<br>+  dim(newTh) &lt;- c(svIter, q);<br>+ <br>+  maxGamma &lt;- 40; # abs(8 / ((max(xx %*% newOmega) - newTh)))<br>+  minGamma &lt;- 1; # abs(1 / ((min(xx %*% newOmega) - newTh)));<br>+  rateGamma &lt;- 2; # (maxGamma - minGamma) / 20;     <br>+  bestCost &lt;- Inf;<br>+<br>+  for(i in 1:svIter) { <br>+<br>+    if ((i %% 25 == 0) &amp;&amp; trace) cat(&quot;.&quot;)<br>+<br>+    th[, noRegimes - 1] &lt;- newTh[i,]<br>+        <br>+    for(newGamma in seq(minGamma, maxGamma, rateGamma)) {<br>+<br>+      gamma[noRegimes - 1] &lt;- newGamma;<br>+<br>+      trfun &lt;- cbind(1, GG(xx, gamma, th))<br>+      <br>+      # We fix the linear parameters here, before optimizing the nonlinear.<br>+      local1 &lt;- apply(trfun, 2, &quot;*&quot;, x_t)<br>+      dim(local1) &lt;- c(n.used, noRegimes * p)<br>+      newPhi1&lt;- lm.fit(x = local1, y = yy)$coefficients<br>+      dim(newPhi1) &lt;- c(NCOL(xx) + 1, noRegimes)<br>+#      newPhi1 &lt;- t(newPhi1)<br>+<br>+      local2 &lt;- (x_t %*% newPhi1) * trfun;<br>+ <br>+      y.hat &lt;- apply(local2, 1, sum)<br>+      cost &lt;- crossprod(yy - y.hat) / sqrt(n.used);<br>+<br>+      if(! <a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465495967000&amp;usg=AOvVaw381WGpgwmY6dYjMLlGEi6o">is.na</a>(cost)) {<br>+        if(cost &lt; bestCost) {<br>+          bestCost &lt;- cost;<br>+<br>+          bestGamma &lt;- gamma<br>+          bestTh &lt;- th<br>+          bestPhi1 &lt;- newPhi1<br>+        }<br>+      }<br>+    }<br>+  }<br>+<br>+  gamma &lt;- bestGamma<br>+  th &lt;- bestTh<br>+  phi1 &lt;- bestPhi1<br>+  <br>+  if (trace) cat(&quot;
  Starting values fixed for regime &quot;, noRegimes,<br>+                 &quot;:
	gamma = &quot;, gamma[noRegimes - 1],<br>+                 &quot;
	th = &quot;, th[,noRegimes - 1], &quot;
