&quot;)<br>+  <br>+#    ordering &lt;-  sort(th, index.return=TRUE)$ix<br>+    <br>+#    th &lt;- sort(th, index.return=TRUE)$x<br>+#    gamma &lt;- gamma[ordering]<br>+#    omega &lt;- omega[, ordering]<br>+#    phi1 &lt;- phi1[ordering,]<br>+#    <br>+#  }<br>+  <br>+  object$model.specific$phi2 &lt;- c(gamma, th)<br>+  object$model.specific$phi1 &lt;- phi1;<br>+  object$model.specific$coefficients &lt;- c(phi1, gamma, th);<br>+  object$coefficients &lt;- c(phi1, gamma, th);<br>+  object$model.specific$k &lt;- length(object$coefficients)<br>+  object$k &lt;- length(object$coefficients)<br>+  <br>+  return(object);<br>+  <br>+}<br>+<br>+estimateParams &lt;- function(object, ...)<br>+  UseMethod(&quot;estimateParams&quot;)<br>+<br>+# Estimates the parameters of a given STAR model.<br>+#<br>+# object: a valid STAR model.<br>+#<br>+# Estimates object$model.specific$phi1<br>+#                   object$model.specific$phi2<br>+estimateParams.ncstar &lt;- function(object, trace=TRUE,<br>+                                  control=list(), alg=&quot;LM&quot;, cluster=NULL, ...)<br>+{<br>+<br>+  xx &lt;- object$str$xx<br>+  x_t &lt;- cbind(1, xx)<br>+  yy &lt;- object$str$yy<br>+  n.used &lt;- NROW(object$str$xx);<br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+  q &lt;- NCOL(xx)<br>+  p &lt;- NCOL(x_t)<br>+<br>+  # Function to compute the gradient <br>+  #<br>+  # Returns the gradient with respect to the error<br>+  gradEhat &lt;- function(par) {<br>+    gamma &lt;- par[1:noRegimes - 1]<br>+    th &lt;- par[noRegimes:length(phi2)]<br>+    dim(th) &lt;- c(q, noRegimes - 1)<br>+    <br>+    # We fix the linear parameters because they&#39;re not known here<br>+    trfun &lt;- GG(xx, gamma, th)<br>+    tmp &lt;- apply(cbind(1, trfun), 2, &quot;*&quot;, x_t)<br>+    dim(tmp) &lt;- c(n.used, noRegimes * p)<br>+    phi1 &lt;- lm.fit(x = tmp, y = yy)$coefficients<br>+    dim(phi1) &lt;- c(p, noRegimes)<br>+    phi1 &lt;- t(phi1)<br>+<br>+    # Compute the gradients<br>+  